/* Translated-GX scene: runs translated PowerPC code that drives GX, then draws the result.
 *
 * Each frame: the guest program (gx_demo_guest.c, generated by tools/make_gx_demo.py) stores
 * GX commands to the write-gather pipe; runtime/hw.c captures them; runtime/gx_cp.c turns
 * them into clip-space triangles; this file draws those with citro3d. The same chain is
 * checked on the host by tests/test_gx_demo.py. MIT License. */
#ifndef SPM3DS_GX_SCENE_H
#define SPM3DS_GX_SCENE_H

#include <3ds.h>
#include <citro3d.h>

#include "gx_cp.h"
#include "hw.h"

typedef struct {
    float pos[4];   /* clip space, tilted for the 3DS top screen */
    float clr[4];
} gx_scene_vertex;

typedef struct {
    shaderProgram_s program;
    DVLB_s *dvlb;
    C3D_AttrInfo attr;
    C3D_BufInfo buf;
    gx_scene_vertex *vbo;
    ppc_ctx *ctx;
    spm3ds_hw *hw;
    gx_cp *cp;
    u32 triangles;     /* drawn in the last frame */
    u32 fifo_bytes;    /* captured in the last frame */
    int error;         /* command processor error flag from the last frame */
} gx_scene;

int gx_scene_create(gx_scene *s);   /* 0 on success, negative step code otherwise */
void gx_scene_frame(gx_scene *s, C3D_RenderTarget *target, float angle_y, float angle_x);
void gx_scene_destroy(gx_scene *s);

#endif /* SPM3DS_GX_SCENE_H */
